const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const state={score:0,best:+localStorage.getItem('andinaBest')||0,gameStart:null,timer:null,lives:3,climb:0,round:0};
$('#bestScore').textContent=state.best;
const safe=(s)=>String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
function toast(t){const x=$('#toast');x.textContent=t;x.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>x.classList.remove('show'),2400)}
function addScore(n){state.score+=n;$('#totalScore').textContent=state.score;if(state.score>state.best){state.best=state.score;localStorage.setItem('andinaBest',state.best);$('#bestScore').textContent=state.best}}
function setClimb(n){state.climb=Math.max(0,Math.min(100,n));$('#climbFill').style.width=state.climb+'%'}
function loseLife(reason='Tiempo agotado'){state.lives--;$('#lives').textContent='❤ '.repeat(state.lives)+'♡ '.repeat(3-state.lives);toast('−1 vida · '+reason);if(state.lives<=0){clearInterval(state.timer);$('#gameArea').innerHTML=`<div class="game-box"><span class="tag">FIN DEL ASCENSO</span><h3>La montaña te pide otro intento.</h3><p>Terminaste con <b>${state.score}</b> puntos. Reinicia y prueba otra vez.</p><button class="primary" id="restartGame">↻ Reiniciar ascenso</button></div>`;$('#restartGame').onclick=resetChallenge}}
function resetChallenge(){state.score=0;state.lives=3;state.round=0;state.climb=0;$('#totalScore').textContent='0';$('#lives').textContent='❤ ❤ ❤';setClimb(0);startClock();renderChallenge()}
function startClock(){clearInterval(state.timer);state.gameStart=Date.now();state.timer=setInterval(()=>{const s=Math.floor((Date.now()-state.gameStart)/1000);$('#gameTime').textContent=String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')},1000)}

