const revealObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add('in-view')}),{threshold:.14,rootMargin:'0px 0px -8% 0px'});$$('.reveal-section').forEach(x=>revealObserver.observe(x));
const navObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){$$('#mainNav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+e.target.id))}}),{rootMargin:'-35% 0px -55% 0px'});$$('.section-anchor').forEach(s=>navObserver.observe(s));
