// Música nativa. El navegador no puede enumerar una carpeta local por seguridad, así que la web trae una pista fija y permite cargar otras.
const audio=$('#audioPlayer');let tracks=[{name:'Andina · ambiente original',url:'music/andina_ambient.wav'}];let current=0;
function rebuildTracks(){const s=$('#trackSelect');s.innerHTML='<option value="">Sin música</option>'+tracks.map((t,i)=>`<option value="${i}">${safe(t.name)}</option>`).join('');if(tracks.length)s.value=String(current)}
function loadTrack(i,autoplay=false){if(!tracks[i])return;current=i;audio.src=tracks[i].url;audio.volume=+$('#musicVolume').value;$('#trackSelect').value=String(i);if(autoplay)audio.play().then(()=>$('#musicToggle').textContent='⏸ Pausar').catch(()=>{});}
rebuildTracks();loadTrack(0);$('#trackSelect').onchange=e=>{if(e.target.value===''){audio.pause();audio.removeAttribute('src');$('#musicToggle').textContent='▶ Reproducir';return}loadTrack(+e.target.value,true)};$('#musicVolume').oninput=e=>audio.volume=+e.target.value;$('#musicLoop').onclick=()=>{audio.loop=!audio.loop;$('#musicLoop').textContent='↻ Repetir: '+(audio.loop?'sí':'no')};$('#musicToggle').onclick=async()=>{if(!audio.src)return toast('Selecciona una pista.');if(audio.paused){try{await audio.play();$('#musicToggle').textContent='⏸ Pausar'}catch{toast('Chrome requiere una interacción para iniciar el audio.')}}else{audio.pause();$('#musicToggle').textContent='▶ Reproducir'}};audio.onended=()=>$('#musicToggle').textContent='▶ Reproducir';$('#musicFiles').onchange=e=>{[...e.target.files].forEach(f=>tracks.push({name:f.name,url:URL.createObjectURL(f)}));rebuildTracks();toast('Canciones añadidas a esta sesión.');};

