function renderGame(){if(gameState.mode==='quiz')renderQuiz();if(gameState.mode==='crossword')renderCrossword();if(gameState.mode==='wordsearch')renderWordSearch();if(gameState.mode==='challenge')resetChallenge();if(gameState.mode==='memory')renderMemory();}
function renderQuiz(){let i=0,points=0;const area=$('#gameArea');function q(){const x=questions[i];area.innerHTML=`<div class="game-box"><span class="tag">QUIZ · ${i+1}/${questions.length}</span><h3>${x[0]}</h3><div class="answer-grid">${x[1].map((a,j)=>`<button class="answer" data-i="${j}">${a}</button>`).join('')}</div><div id="qres"></div></div>`;$$('.answer').forEach(b=>b.onclick=()=>{if($$('.answer').some(x=>x.disabled))return;const ok=+b.dataset.i===x[2];b.classList.add(ok?'correct':'wrong');if(ok){points++;addScore(100)}else $$('.answer')[x[2]].classList.add('correct');$$('.answer').forEach(z=>z.disabled=true);$('#qres').innerHTML=`<div class="result">${ok?'¡Correcto! +100':'Casi. Mira la respuesta correcta.'} <button class="small-btn" id="nextQ">${i===questions.length-1?'Finalizar':'Siguiente'}</button></div>`;$('#nextQ').onclick=()=>{i++;if(i<questions.length)q();else{area.innerHTML=`<div class="game-box"><span class="tag">RESULTADO</span><h3>Quiz terminado</h3><p>Acertaste ${points} de ${questions.length}.</p><button class="primary" id="againQ">↻ Repetir</button></div>`;$('#againQ').onclick=()=>renderQuiz()}}})}q()}

// Crucigrama real: palabras horizontales y verticales compartiendo letras.
const crossword={size:17,placements:[
 ['ANDES',8,5,0,1],['CAFE',5,8,1,0],['CAUCA',7,5,1,0],['PARAMO',11,4,0,1],['CONDOR',10,9,1,0],['MAGDALENA',13,6,0,1],['BOGOTA',8,14,1,0],['CULTURA',15,4,0,1],['CHINGAZA',5,8,0,1]
],clues:[['ANDES','Sistema montañoso que atraviesa Colombia.'],['CAFE','Producto agrícola emblemático de varias zonas andinas.'],['CAUCA','Río de un gran valle interandino.'],['PARAMO','Ecosistema de alta montaña clave para el agua.'],['CONDOR','Ave emblemática de los Andes.'],['MAGDALENA','Río que forma un importante valle interandino.'],['BOGOTA','Capital ubicada en la cordillera Oriental.'],['CULTURA','Conjunto de prácticas, tradiciones y expresiones de una sociedad.'],['CHINGAZA','Área protegida andina conocida por sus ecosistemas de montaña.']]};
function crossGrid(){const g=Array.from({length:crossword.size},()=>Array(crossword.size).fill(null));for(const [w,r,c,dr,dc] of crossword.placements){for(let i=0;i<w.length;i++)g[r+dr*i][c+dc*i]=w[i]}return g}
function renderCrossword(){const g=crossGrid();let cells='';for(let r=0;r<17;r++)for(let c=0;c<17;c++){if(g[r][c])cells+=`<div class="cross-cell"><input maxlength="1" data-r="${r}" data-c="${c}" data-answer="${g[r][c]}" aria-label="Fila ${r+1}, columna ${c+1}"></div>`;else cells+='<div class="cross-cell blocked"></div>'}$('#gameArea').innerHTML=`<div class="game-box"><span class="tag">CRUCIGRAMA · HORIZONTAL + VERTICAL</span><h3>Las palabras se atraviesan.</h3><p>Completa las palabras usando las letras compartidas. Puedes resolver una pista y usar sus cruces para descubrir otra.</p><div class="cross-grid">${cells}</div><div class="cross-clues">${crossword.clues.map((x,i)=>`<div><b>${i+1}. ${x[0]}</b><br>${x[1]}</div>`).join('')}</div><button class="primary" id="checkCross" style="margin-top:20px">Comprobar</button><div id="crossRes"></div></div>`;$('#checkCross').onclick=()=>{let ok=0,total=0;$$('.cross-cell input').forEach(i=>{total++;const good=i.value.toUpperCase()===i.dataset.answer;i.classList.toggle('good',good);i.classList.toggle('bad',!good);if(good)ok++});addScore(ok*10);$('#crossRes').innerHTML=`<div class="result">${ok}/${total} letras correctas · +${ok*10}</div>`}}

