$$('[data-detail]').forEach(b=>b.onclick=()=>{const d=detailData[b.dataset.detail];if(!d)return;$('#modalContent').innerHTML=`<span class="tag">EXPLORA</span><h2>${d[0]}</h2><p>${d[1]}</p><div class="detail-extra"><b>Pregunta guía</b><span>¿Cómo se relaciona este tema con la forma en que se vive y se transforma el territorio andino?</span></div>`;$('#modal').classList.add('show')});
